param([Parameter(Mandatory=$true)][string]$RunId,[string]$DeviceId='emulator-5554')
$root=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path; $out=Join-Path $root "artifacts\cayenne\runs\$RunId"; New-Item -ItemType Directory -Force (Join-Path $out 'hierarchies'),(Join-Path $out 'logs'),(Join-Path $out 'screenshots') | Out-Null; & adb -s $DeviceId exec-out uiautomator dump /dev/tty | Out-File (Join-Path $out 'hierarchies\final.xml') -Encoding utf8; & adb -s $DeviceId logcat -d -t 500 | Out-File (Join-Path $out 'logs\logcat.txt') -Encoding utf8; & adb -s $DeviceId exec-out screencap -p > (Join-Path $out 'screenshots\final.png')
